const labels={library:'私人收藏',packs:'任務套組',tools:'工具配置'};
const initialView=new URL(location.href).searchParams.get('screen');
const state={view:labels[initialView]?initialView:'library',focus:'research',pack:'planning',query:'',filter:'all',tag:'',source:'',selected:new Set(),detailTab:'overview',tool:'Codex',scope:'global',modal:null};
const environments={};
const getEnvironment=(tool=state.tool,scope=state.scope)=>{
 const key=tool+':'+scope;
 if(!environments[key]) environments[key]=tool==='Codex'&&scope==='global' ? [{id:'research',status:'good',enabled:true},{id:'code-review',status:'warning',enabled:true},{id:'tdd',status:'good',enabled:true},{id:'custom-workflow',status:'external',enabled:true},{id:'domain-modeling',status:'missing',enabled:false}] : scope==='project' ? [{id:'research',status:'good',enabled:true},{id:'tdd',status:'good',enabled:true}] : [{id:'grilling',status:'good',enabled:true},{id:'research',status:'good',enabled:true}];
 return environments[key];
};
const isEnabled=(id,tool)=>getEnvironment(tool,'global').some(r=>r.id===id&&r.enabled);
const skill=id=>skills.find(s=>s.id===id);
const pack=()=>packs.find(p=>p.id===state.pack)||packs[0];
const toolPath=(tool=state.tool,scope=state.scope)=>`${scope==='global'?'~':'~/workspace/skillsHub'}/${tool==='Codex'?'.agents':'.claude'}/skills`;
function toast(text){$('toast').textContent=text;$('toast').hidden=false;clearTimeout(window.toastTimer);window.toastTimer=setTimeout(()=>$('toast').hidden=true,3500);}
function sidebar(){ $('sidebar').innerHTML=`<div class="brand"><span class="mark">s<span hidden>hub</span></span><span class="wordmark">skillshub<span style="color:#b78969">.</span></span></div><div class="workspace-switch"><span class="avatar">CY</span><div>我的工作空間<small>PERSONAL WORKSPACE</small></div></div><p class="section-label">工作區</p>${Object.entries(labels).map(([id,label])=>`<button class="nav ${state.view===id?'active':''}" data-screen="${id}" title="${label}">${icon(id)}<span class="nav-text">${label}</span><span class="count">${id==='library'?skills.length:id==='packs'?packs.length:'2'}</span></button>`).join('')}<div class="sidebar-divider"></div><div class="sidebar-extra"><p class="section-label">快速存取</p><button class="nav ${state.view==='library'&&state.filter==='favorites'?'active':''}" data-filter="favorites">${icon('star')}<span>常用收藏</span><span class="count">${skills.filter(s=>s.favorite).length}</span></button><button class="nav" data-filter="recent">${icon('clock')}最近收錄</button><div class="sidebar-divider"></div><p class="section-label">我的標籤</p>${['研究','規劃','開發','寫作'].map((t,i)=>`<button class="nav" data-tag="${t}"><span class="label-dot" style="background:${['#a194ba','#b5a073','#81a3ac','#b38b87'][i]}"></span>${t}</button>`).join('')}</div><div class="sidebar-bottom"><b><span class="live-dot"></span>本機工作空間</b>介面預覽 · 使用展示資料<br>重新整理即可重置變更</div>`; }
function render(){sidebar();$('topbar').innerHTML=`<div class="crumb">我的工作空間<span>/</span><b style="font-weight:500;color:#616b76">${labels[state.view]}</b></div><div class="top-actions"><span class="prototype-badge">MOCKUP · 不會變更檔案</span><span class="avatar">CY</span></div>`; $('workspace').innerHTML=state.view==='library'?library():state.view==='packs'?packPage():toolsPage();bindInputs();}
function go(view){state.view=view;const url=new URL(location.href);url.searchParams.set('screen',view);history.replaceState({},'',url);render();}
function library(){
 const q=state.query.toLowerCase();let rows=skills.filter(s=>(state.filter!=='favorites'||s.favorite)&&(!state.tag||s.tag===state.tag)&&(!state.source||s.source===state.source)&&(!q||[s.id,s.cn,s.desc,s.note,s.tag].join(' ').toLowerCase().includes(q)));
 if(state.filter==='recent')rows=[...rows].reverse();
 return `<div class="heading"><div><h1>${state.filter==='favorites'?'常用收藏':state.filter==='recent'?'最近收錄':state.tag||'私人收藏'}</h1><p>收藏好的方法，在需要的時候找到它。</p></div><button class="primary" data-action="import">${icon('plus')}收錄 Skill</button></div><div class="toolbar"><label class="search">${icon('search')}<input id="search" aria-label="搜尋收藏" placeholder="搜尋名稱、中文用途或筆記…" value="${esc(state.query)}"><kbd>/</kbd></label><div class="filters"><select id="tag-filter" aria-label="標籤"><option value="">所有標籤</option>${[...new Set(skills.map(s=>s.tag))].map(t=>`<option ${state.tag===t?'selected':''}>${t}</option>`).join('')}</select><select id="source-filter" aria-label="來源"><option value="">所有來源</option><option ${state.source==='mattpocock/skills'?'selected':''}>mattpocock/skills</option><option ${state.source==='本機收藏'?'selected':''}>本機收藏</option></select><button class="icon-button" data-action="reset-filters" title="清除篩選">${icon('settings')}</button></div></div><div class="library-layout"><div class="library-main"><div class="list-caption"><span>${rows.length} 個 Skill${state.selected.size?` · 已選 ${state.selected.size} 個`:''}</span><span>${state.filter==='recent'?'依收錄時間':'自訂順序'}</span></div><table class="skill-list"><thead><tr><th><input type="checkbox" id="select-all" aria-label="選取所有顯示項目" ${rows.length&&rows.every(s=>state.selected.has(s.id))?'checked':''}></th><th>SKILL / 用途</th><th class="tag-column">標籤</th><th>已配置</th></tr></thead><tbody>${rows.map(s=>`<tr class="${state.focus===s.id?'selected':''}"><td><input type="checkbox" data-select="${s.id}" aria-label="選取 ${s.id}" ${state.selected.has(s.id)?'checked':''}></td><td><button class="skill-name" data-focus="${s.id}">${esc(s.id)} ${s.favorite?'<span class="star">⋆</span>':''}</button><div class="skill-sub">${s.cn}</div></td><td class="tag-column"><span class="tag">${s.tag}</span></td><td><div class="tool-chips">${['Codex','Claude Code'].filter(t=>isEnabled(s.id,t)).map(t=>`<span class="tool-chip">${t==='Codex'?'Codex':'Claude'}</span>`).join('')||'<span class="muted">—</span>'}</div></td></tr>`).join('')}</tbody></table>${!rows.length?'<div class="empty-row">沒有符合的收藏，試試其他搜尋條件。</div>':''}</div>${detail()}</div>${state.selected.size?`<div class="selection-bar"><span>已選取 ${state.selected.size} 個 Skill</span><button data-action="clear-selected">清除</button><button data-action="add-to-pack">加入套組</button><button class="primary" data-action="configure-selected">配置到工具 ${icon('arrow')}</button></div>`:''}`;
}
function detail(){const s=skill(state.focus);const ownPacks=packs.filter(p=>p.members.includes(s.id));return `<aside class="detail"><div class="detail-top"><span class="skill-symbol">${icon('file')}</span><button class="icon-button ${s.favorite?'star':''}" data-favorite="${s.id}" aria-label="${s.favorite?'取消':'加入'}常用收藏">${icon('star')}</button></div><h2>${s.id}</h2><div class="cn-title">${s.cn}</div><h3>什麼時候用</h3><p>${s.use}</p><h3>我的筆記 <button class="quiet" style="padding:0 0 0 8px;font-size:9px" data-action="edit-note">編輯</button></h3><div class="note"><span>PERSONAL NOTE · 展示資料</span>${esc(s.note)||'還沒有筆記，記下適合自己的使用方式。'}</div><h3>所屬任務套組</h3><div class="inline-tags">${ownPacks.map(p=>`<button class="kit-chip" data-pack="${p.id}">${icon('packs')} ${p.name}</button>`).join('')||'<span class="muted">尚未加入套組</span>'}</div><h3>工具配置</h3><div class="detail-tools"><div class="detail-tool">Codex<small class="${isEnabled(s.id,'Codex')?'':'off'}">${isEnabled(s.id,'Codex')?'● 全域啟用':'○ 尚未配置'}</small></div><div class="detail-tool">Claude Code<small class="${isEnabled(s.id,'Claude Code')?'':'off'}">${isEnabled(s.id,'Claude Code')?'● 全域啟用':'○ 尚未配置'}</small></div></div><div class="tabs">${[['overview','原始文件'],['files','附帶檔案'],['source','來源']].map(([id,label])=>`<button class="tab ${state.detailTab===id?'active':''}" data-tab="${id}">${label}</button>`).join('')}</div><div class="file-preview">${state.detailTab==='overview'?`<b>${s.id} / SKILL.md</b><br>${s.desc}<br><small>此處為文件預覽示意</small>`:state.detailTab==='files'?`${icon('file')} SKILL.md<br>${icon('folder')} agents/<br>　└ openai.yaml<br><small>展示用檔案樹</small>`:`來源：${s.source}<br>收錄時間：2026 / 10 / 29<br>版本：a84c2e1（展示）`}</div><div class="detail-footer"><button class="secondary" data-action="add-focused">加入套組</button><button class="primary" data-action="configure-focused">配置到工具 ${icon('arrow')}</button></div></aside>`;}
function packPage(){const p=pack();return `<div class="heading"><div><h1>任務套組</h1><p>把常用的方法放在一起，為下一次工作做好準備。</p></div><button class="primary" data-action="new-pack">${icon('plus')}建立套組</button></div><div class="packs-layout"><div class="pack-list">${packs.map(k=>`<button class="pack-card ${k.id===p.id?'active':''}" data-pack="${k.id}"><div class="pack-top"><span class="pack-icon">${icon(k.icon)}</span><h3>${esc(k.name)}</h3></div><p>${esc(k.desc)}</p><footer><span>${k.members.length} 個 Skills</span><span>${k.id==='planning'?'最近編輯':'私人套組'}</span></footer></button>`).join('')}<button class="create-pack" data-action="new-pack">＋ 建立自己的任務套組</button></div><section class="pack-editor"><div class="pack-editor-head"><div><div class="eyebrow">PERSONAL PLAYBOOK</div><h2>${esc(p.name)}</h2><p>${esc(p.purpose)}</p></div><button class="secondary" data-action="edit-pack">編輯用途</button></div><div class="pack-editor-body"><div class="subheading"><h3>套組成員 <span> / ${p.members.length}</span></h3><button class="quiet" data-action="add-members">＋ 從收藏加入</button></div>${p.members.map((id,i)=>{const s=skill(id);return `<article class="pack-member"><span class="member-index">0${i+1}</span><div class="member-main"><h4>${id}</h4><p>${s.cn}</p><div class="why">${esc(p.reasons[i]||'已加入此套組；可再補充使用提示。')}</div></div><div class="member-actions"><button data-move="${i}" data-direction="-1" aria-label="將 ${id} 上移" ${i===0?'disabled':''}>↑</button><button data-move="${i}" data-direction="1" aria-label="將 ${id} 下移" ${i===p.members.length-1?'disabled':''}>↓</button><button data-remove="${id}" aria-label="從套組移除 ${id}">×</button></div></article>`}).join('')||'<div class="empty-row">從收藏加入第一個 Skill。</div>'}<div class="helper">排列順序是你的使用提示。套用這個套組只會配置 Skills，不會自動依序執行。</div></div><div class="pack-editor-footer"><span>變更僅保留在這次預覽，尚未套用到任何工具。</span><button class="primary" data-action="apply-pack">套用到工具 ${icon('arrow')}</button></div></section></div>`;}
function toolsPage(){const rows=getEnvironment(),status={good:'內容一致',warning:'本機內容有修改',external:'尚未納入收藏',missing:'配置已失效'};return `<div class="heading"><div><h1>工具配置</h1><p>看清每個工具正在使用什麼，讓配置保持在掌握之中。</p></div><button class="secondary" data-action="refresh">${icon('clock')}重新檢查</button></div><div class="config-wrap"><div class="target-bar"><span class="tool-logo">${state.tool==='Codex'?'⌘':'✳'}</span><label>目標工具<select id="target-tool"><option ${state.tool==='Codex'?'selected':''}>Codex</option><option ${state.tool==='Claude Code'?'selected':''}>Claude Code</option></select></label><span class="target-divider"></span><label>作用範圍<select id="target-scope"><option value="global" ${state.scope==='global'?'selected':''}>全域 · 所有專案</option><option value="project" ${state.scope==='project'?'selected':''}>專案 · skillsHub</option></select></label><code class="target-path">${toolPath()}</code></div><section class="config-panel"><div class="config-panel-head"><h2>目前的 Skills <span>${rows.length} 個項目</span></h2><div class="config-actions"><button class="secondary" data-action="configure-from-library">＋ 從收藏加入</button><button class="primary" data-action="choose-pack">${icon('packs')}套用任務套組</button></div></div><table class="config-table"><thead><tr><th>SKILL / 用途</th><th>目前狀態</th><th class="source-col">管理來源</th><th>啟用 / 操作</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b style="font-weight:600">${r.id}</b><div class="skill-sub">${skill(r.id)?.cn||'專案自訂工作流程'}</div></td><td><span class="status ${r.status}">${status[r.status]}</span>${r.status==='warning'?'<button class="text-link" data-action="diff">查看差異</button>':''}</td><td class="source-col"><span class="muted">${r.status==='external'?'工具內既有項目':'私人收藏'}</span></td><td><div class="row-actions">${r.status==='external'?'<button class="secondary" data-action="adopt">查看 / 收錄</button>':r.status==='missing'?`<button class="secondary" data-repair="${r.id}">重新配置</button>`:`<button class="switch ${r.enabled?'on':''}" data-toggle="${r.id}" role="switch" aria-checked="${r.enabled}" aria-label="${r.enabled?'停用':'啟用'} ${r.id}"></button><span class="muted" style="font-size:9px">${r.enabled?'已啟用':'已停用'}</span>`}</div></td></tr>`).join('')}</tbody></table><div class="config-footnote">停用只影響所選工具，私人收藏仍會保留。非本工具管理的項目需先檢視，再決定是否收錄。</div></section><div class="activity"><h3>最近配置活動 <span class="muted" style="font-weight:400"> / 展示紀錄</span></h3><div class="activity-row"><time>10:42</time><span>將 <b>research</b> 配置到 Codex · 全域</span></div><div class="activity-row"><time>昨天</time><span>套用 <b>程式品質</b> 套組 · 3 個 Skills</span></div></div></div>`;}
function bindInputs(){
 if($('search'))$('search').oninput=e=>{const start=e.target.selectionStart;state.query=e.target.value;render();$('search').focus();$('search').setSelectionRange(start,start);};
 if($('tag-filter'))$('tag-filter').onchange=e=>{state.tag=e.target.value;render();};
 if($('source-filter'))$('source-filter').onchange=e=>{state.source=e.target.value;render();};
 if($('select-all'))$('select-all').onchange=e=>{document.querySelectorAll('[data-select]').forEach(c=>e.target.checked?state.selected.add(c.dataset.select):state.selected.delete(c.dataset.select));render();};
 if($('target-tool'))$('target-tool').onchange=e=>{state.tool=e.target.value;render();};
 if($('target-scope'))$('target-scope').onchange=e=>{state.scope=e.target.value;render();};
}
function modal(title,body,footer='',eyebrow='INTERFACE PREVIEW'){ $('modal').innerHTML=`<div class="modal-head"><div><div class="eyebrow">${eyebrow}</div><h2>${title}</h2></div><button class="icon-button" data-action="close" aria-label="關閉">${icon('close')}</button></div><div class="modal-body">${body}</div><div class="modal-footer"><button class="secondary" data-action="close">取消</button>${footer}</div>`;if(!$('modal').open)$('modal').showModal(); }
function pickPack(ids){state.pendingIds=ids;modal('加入任務套組',`<p>將 ${ids.length} 個選取的 Skill 加入套組。已存在的成員會略過。</p>${packs.map((p,i)=>`<label class="choice-row"><input type="radio" name="pack-choice" value="${p.id}" ${i===0?'checked':''}><div>${esc(p.name)}<small>${p.members.length} 個 Skills · ${esc(p.desc)}</small></div></label>`).join('')}`, '<button class="primary" data-action="confirm-add-pack">加入套組</button>');}
function configure(ids){if(!ids.length){toast('請先加入至少一個 Skill');return;}state.pendingIds=ids;modal('配置到工具',`<p>選擇目標環境，下一步會列出每個 Skill 的預計變更。</p><label class="field">目標工具<select id="configure-tool"><option ${state.tool==='Codex'?'selected':''}>Codex</option><option ${state.tool==='Claude Code'?'selected':''}>Claude Code</option></select></label><label class="field">作用範圍<select id="configure-scope"><option value="global" ${state.scope==='global'?'selected':''}>全域 · 所有專案</option><option value="project" ${state.scope==='project'?'selected':''}>專案 · skillsHub</option></select></label><div class="summary-box">已選 ${ids.length} 個 Skill：${ids.map(esc).join('、')}</div>`, '<button class="primary" data-action="preview-config">預覽變更 →</button>');}
function previewConfig(){state.tool=$('configure-tool').value;state.scope=$('configure-scope').value;const env=getEnvironment();const changes=state.pendingIds.map(id=>{const row=env.find(r=>r.id===id);return {id,action:row?.status==='warning'?'conflict':row?.enabled?'skip':'add'};});state.changes=changes;modal('確認配置變更',`<p>${state.tool} · ${state.scope==='global'?'全域':'skillsHub 專案'}</p><div class="summary-box">${changes.filter(c=>c.action==='add').length} 個新增 · ${changes.filter(c=>c.action==='skip').length} 個已存在 · ${changes.filter(c=>c.action==='conflict').length} 個衝突</div>${changes.map(c=>`<div class="change-row"><div>${c.id}<small>${toolPath()}/${c.id}</small></div><em class="${c.action==='add'?'':'skip'}">${{add:'新增配置',skip:'已存在 · 略過',conflict:'內容不同 · 保留'}[c.action]}</em></div>`).join('')}<p style="margin-top:17px">保留目標環境原有的其他 Skills；內容衝突不覆寫。</p>`, '<button class="primary" data-action="confirm-config">模擬套用變更</button>', 'REVIEW CHANGES');}
document.addEventListener('click',e=>{
 const el=e.target.closest('button,[data-select]');if(!el)return;
 if(el.dataset.screen){state.filter='all';state.tag='';go(el.dataset.screen);return;}
 if(el.dataset.filter){state.filter=el.dataset.filter;state.tag='';go('library');return;}
 if(el.dataset.tag){state.tag=el.dataset.tag;state.filter='all';go('library');return;}
 if(el.dataset.focus){state.focus=el.dataset.focus;render();return;}
 if(el.dataset.select){el.checked?state.selected.add(el.dataset.select):state.selected.delete(el.dataset.select);render();return;}
 if(el.dataset.favorite){const s=skill(el.dataset.favorite);s.favorite=!s.favorite;render();return;}
 if(el.dataset.tab){state.detailTab=el.dataset.tab;render();return;}
 if(el.dataset.pack){state.pack=el.dataset.pack;go('packs');return;}
 if(el.dataset.move!==undefined){const p=pack(),from=Number(el.dataset.move),to=from+Number(el.dataset.direction);[p.members[from],p.members[to]]=[p.members[to],p.members[from]];[p.reasons[from],p.reasons[to]]=[p.reasons[to],p.reasons[from]];render();return;}
 if(el.dataset.remove){const p=pack(),i=p.members.indexOf(el.dataset.remove);p.members.splice(i,1);p.reasons.splice(i,1);render();toast('已從展示套組移除，私人收藏仍保留');return;}
 if(el.dataset.toggle){const row=getEnvironment().find(r=>r.id===el.dataset.toggle);state.toggleId=row.id;modal(row.enabled?'停用這個 Skill？':'啟用這個 Skill？',`<p>${row.id} · ${state.tool}</p><div class="change-row"><div>${row.enabled?'移除此工具的啟用關係':'恢復此工具的啟用關係'}<small>${toolPath()}/${row.id}</small></div><em class="${row.enabled?'remove':''}">${row.enabled?'停用':'啟用'}</em></div><p style="margin-top:15px">私人收藏與任務套組都會保留。這次只模擬畫面狀態。</p>`,'<button class="primary" data-action="confirm-toggle">確認模擬變更</button>');return;}
 if(el.dataset.repair){configure([el.dataset.repair]);return;}
 const action=el.dataset.action;
 if(action==='close')$('modal').close();
 if(action==='clear-selected'){state.selected.clear();render();}
 if(action==='reset-filters'){state.query='';state.tag='';state.source='';state.filter='all';render();}
 if(action==='add-focused')pickPack([state.focus]);
 if(action==='add-to-pack')pickPack([...state.selected]);
 if(action==='configure-focused')configure([state.focus]);
 if(action==='configure-selected')configure([...state.selected]);
 if(action==='apply-pack')configure([...pack().members]);
 if(action==='confirm-add-pack'){const p=packs.find(p=>p.id===document.querySelector('[name=pack-choice]:checked').value);for(const id of state.pendingIds)if(!p.members.includes(id)){p.members.push(id);p.reasons.push('依這次任務需要加入。');}$('modal').close();render();toast(`已加入「${p.name}」展示套組`);}
 if(action==='new-pack'||action==='edit-pack'){state.editingPack=action==='edit-pack'?pack().id:null;const p=state.editingPack?pack():{name:'',purpose:''};modal(state.editingPack?'編輯套組用途':'建立任務套組',`<label class="field">套組名稱<input id="pack-name" placeholder="例如：產品需求規劃" value="${esc(p.name)}" maxlength="40"></label><label class="field">什麼時候使用<textarea id="pack-purpose" rows="3" placeholder="描述這組 Skills 可以幫你完成什麼…">${esc(p.purpose)}</textarea></label>`,'<button class="primary" data-action="save-pack">儲存展示套組</button>');}
 if(action==='save-pack'){const name=$('pack-name').value.trim(),purpose=$('pack-purpose').value.trim();if(!name){$('pack-name').focus();return;}if(state.editingPack){const p=pack();p.name=name;p.purpose=purpose;p.desc=purpose.slice(0,45);}else{const id='custom-'+Date.now();packs.push({id,name,desc:purpose,purpose,members:[],reasons:[],icon:'packs'});state.pack=id;}$('modal').close();go('packs');toast('已儲存於這次預覽');}
 if(action==='add-members'||action==='configure-from-library'){state.pickerMode=action;modal(action==='add-members'?'從私人收藏加入':'選擇要配置的 Skills',`<p>勾選需要的 Skills，既有項目會保留。</p>${skills.map(s=>`<label class="choice-row"><input type="checkbox" name="member-choice" value="${s.id}" ${action==='add-members'&&pack().members.includes(s.id)?'checked disabled':''}><div>${s.id}<small>${s.cn}</small></div></label>`).join('')}`, '<button class="primary" data-action="save-members">確認選取</button>');}
 if(action==='save-members'){const ids=[...document.querySelectorAll('[name=member-choice]:checked:not(:disabled)')].map(el=>el.value);if(!ids.length){toast('請先選取至少一個 Skill');return;}if(state.pickerMode==='configure-from-library')configure(ids);else{const p=pack();for(const id of ids){p.members.push(id);p.reasons.push('依這次任務需要加入。');}$('modal').close();render();}}
 if(action==='edit-note')modal('編輯使用筆記',`<p>${state.focus} · 僅編輯展示資料</p><label class="field">我的筆記<textarea id="note" rows="4">${esc(skill(state.focus).note)}</textarea></label>`,'<button class="primary" data-action="save-note">儲存筆記</button>');
 if(action==='save-note'){skill(state.focus).note=$('note').value;$('modal').close();render();}
 if(action==='preview-config')previewConfig();
 if(action==='confirm-config'){const env=getEnvironment();for(const c of state.changes.filter(c=>c.action==='add')){let row=env.find(r=>r.id===c.id);if(row){row.enabled=true;row.status='good';}else env.push({id:c.id,enabled:true,status:'good'});}$('modal').close();go('tools');toast('模擬配置完成，沒有變更任何真實檔案');}
 if(action==='confirm-toggle'){const row=getEnvironment().find(r=>r.id===state.toggleId);row.enabled=!row.enabled;$('modal').close();render();toast('展示狀態已更新，收藏仍保留');}
 if(action==='choose-pack')modal('套用任務套組',`<p>選擇一組常用方法，接著預覽工具配置變更。</p>${packs.map((p,i)=>`<label class="choice-row"><input type="radio" name="apply-pack-choice" value="${p.id}" ${i===0?'checked':''}><div>${esc(p.name)}<small>${p.members.length} 個 Skills · ${esc(p.desc)}</small></div></label>`).join('')}`,'<button class="primary" data-action="configure-pack-choice">下一步 →</button>');
 if(action==='configure-pack-choice'){const p=packs.find(p=>p.id===document.querySelector('[name=apply-pack-choice]:checked').value);configure([...p.members]);}
 if(action==='diff')modal('檢視內容差異','<p>code-review · 私人收藏與工具內版本的比較示意</p><div class="diff">  # Review workflow\n  Check standards and specification.\n<span class="removed">− Report actionable findings.</span>\n<span class="added">+ Report findings in Traditional Chinese.</span>\n<span class="added">+ Include a short verification checklist.</span></div><p style="margin-top:17px">工具內有本機修改。保留目前版本，稍後再決定是否同步。</p>','<button class="primary" data-action="close">保留本機版本</button>');
 if(action==='adopt')modal('查看工具內既有項目','<p>custom-workflow · 展示用範例</p><div class="summary-box">此 Skill 目前存在於工具目錄，尚未納入私人收藏。</div><p>收錄後可以加筆記、加入套組，再決定是否交由 SkillsHub 管理。</p>','<button class="primary" data-action="simulate-adopt">模擬收錄</button>');
 if(action==='simulate-adopt'){if(!skill('custom-workflow'))skills.push({id:'custom-workflow',cn:'專案自訂工作流程',tag:'開發',source:'本機收藏',desc:'專案自訂的工作流程。',use:'依這個專案的特定需求使用。',note:'',favorite:false});const r=getEnvironment().find(r=>r.id==='custom-workflow');if(r)r.status='good';$('modal').close();render();toast('已納入展示收藏');}
 if(action==='refresh')toast('狀態已更新（展示資料，未讀取本機檔案）');
 if(action==='import')modal('收錄新的 Skill','<p>先選擇來源，掃描後再挑選想留下的項目。</p><label class="field">來源類型<select><option>GitHub 儲存庫</option><option>本機資料夾</option></select></label><label class="field">來源位置<input placeholder="https://github.com/owner/repo"></label><div class="helper">這個流程使用固定展示結果，不會下載或讀取來源。</div>','<button class="primary" data-action="scan-import">預覽掃描結果 →</button>');
 if(action==='scan-import')modal('挑選要收錄的 Skills',`<p>掃描結果示意 · 3 個項目</p><label class="choice-row"><input type="checkbox" name="import-choice" checked><div>frontend-design<small>新項目 · 設計前端介面</small></div></label><label class="choice-row"><input type="checkbox" disabled><div>research<small>相同內容已收錄 · 自動略過</small></div></label><label class="choice-row"><input type="checkbox" disabled><div>code-review<small>同名內容不同 · 保留現有收藏</small></div></label>`,'<button class="primary" data-action="finish-import">收錄選取項目</button>');
 if(action==='finish-import'){if(document.querySelector('[name=import-choice]:checked')&&!skill('frontend-design'))skills.unshift({id:'frontend-design',cn:'設計與建立前端介面',tag:'開發',source:'展示來源',desc:'建立具有一致視覺方向的介面。',use:'需要設計網頁與互動介面時。',note:'',favorite:false});$('modal').close();go('library');toast('已完成模擬收錄');}
});
document.addEventListener('keydown',e=>{if(e.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!$('modal').open&&$('search')){e.preventDefault();$('search').focus();}});
render();
